import{_ as n,o as t,c as r,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Opening Ceremony & Land Acknowledgment - Noble Wolf","description":"","frontmatter":{"title":"Opening Ceremony & Land Acknowledgment - Noble Wolf","date":"2025-11-21T00:00:00.000Z","updated":"2025-11-22T00:00:00.000Z","tags":["Ceph技术会议","分布式存储","Ceph社区","Ceph性能优化","多云集成"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Opening_Ceremony_Land_Acknowledgment_-_Noble_Wolf.md","filePath":"posts/2025/Opening_Ceremony_Land_Acknowledgment_-_Noble_Wolf.md","lastUpdated":1780459816000}'),s={name:"posts/2025/Opening_Ceremony_Land_Acknowledgment_-_Noble_Wolf.md"};function l(i,o,g,a,p,d){return t(),r("div",null,[...o[0]||(o[0]=[e('<h3 id="ceph-北美技术交流会纪要" tabindex="-1">Ceph 北美技术交流会纪要 <a class="header-anchor" href="#ceph-北美技术交流会纪要" aria-label="Permalink to &quot;Ceph 北美技术交流会纪要&quot;">​</a></h3><p><strong>会议主题</strong>：Ceph North America 技术交流会<br><strong>会议地点</strong>：加拿大温哥华（原住民 Musquam、Squamish 和 Swit 领地）<br><strong>开场致辞</strong>：原住民文化代表 Nova Wolf（Poentin）<br><strong>主持人</strong>：Ceph 社区成员</p><h4 id="一、开场与文化致谢" tabindex="-1"><strong>一、开场与文化致谢</strong> <a class="header-anchor" href="#一、开场与文化致谢" aria-label="Permalink to &quot;**一、开场与文化致谢**&quot;">​</a></h4><ol><li><p><strong>原住民文化分享</strong>：</p><ul><li>Nova Wolf（Poentin）以传统语言自我介绍，强调了语言与文化传承的重要性。</li><li>分享了 Musquim Indian Warriors 舞蹈团体的历史，展示其为温哥华加人队设计的 <strong>Truth and Reconciliation Logo</strong>，并阐述了原住民的价值观：“一心一意”（one heart, one mind）。</li></ul></li><li><p><strong>土地致谢（Land Acknowledgement）</strong>：</p><ul><li>会议在 Musquam、Squamish 和 Swit 原住民的传统领地上举行，表达了对原住民历史与主权的尊重。</li></ul></li></ol><h4 id="二、ceph-会议核心内容" tabindex="-1"><strong>二、Ceph 会议核心内容</strong> <a class="header-anchor" href="#二、ceph-会议核心内容" aria-label="Permalink to &quot;**二、Ceph 会议核心内容**&quot;">​</a></h4><ol><li><p><strong>会议目标</strong>：</p><ul><li>促进 Ceph 社区在北美地区的协作，分享分布式存储领域的最新进展。</li><li>重点议题包括：<strong>CRUSH algorithm</strong>、<strong>Bluestore/BlueFS</strong> 优化、<strong>RADOS</strong> 性能调优、多云集成等。</li></ul></li><li><p><strong>技术讨论重点</strong>：</p><ul><li><strong>存储架构</strong>：讨论了 <strong>OSD</strong> 的故障域配置与恢复策略，以及 <strong>erasure coding</strong> 与 <strong>replication</strong> 的取舍。</li><li><strong>性能优化</strong>：分享了 <strong>RocksDB</strong> 在 <strong>Bluestore</strong> 中的调优实践和分层存储中 <strong>SSD/HDD</strong> 的缓存策略。</li><li><strong>安全与集成</strong>：讨论了 <strong>RGW</strong> 的 <strong>RESTful API</strong> 认证增强和 <strong>Kubernetes</strong> 与 <strong>Ceph</strong> 的容器化集成。</li></ul></li><li><p><strong>社区动态</strong>：</p><ul><li><strong>Ceph Dashboard</strong> 新增了支持 <strong>iSCSI/NFS</strong> 监控的功能。</li><li>呼吁贡献者参与 <strong>PG</strong> 自动均衡的开发。</li></ul></li></ol><h4 id="三、行动计划" tabindex="-1"><strong>三、行动计划</strong> <a class="header-anchor" href="#三、行动计划" aria-label="Permalink to &quot;**三、行动计划**&quot;">​</a></h4><ol><li><p><strong>短期任务</strong>：</p><ul><li>成立工作组，整理 <strong>CRUSH algorithm</strong> 在多数据中心部署的最佳实践文档。</li><li>针对 <strong>radosgw</strong> 的 <strong>encryption</strong> 功能进行联合测试。</li></ul></li><li><p><strong>长期协作</strong>：</p><ul><li>推动 <strong>CephFS</strong> 对 <strong>POSIX</strong> 标准的兼容性改进，招募开发者参与。</li><li>计划在下一届会议中展示 <strong>deduplication</strong> 与 <strong>compression</strong> 的基准测试结果。</li></ul></li></ol><h4 id="四、闭幕与致谢" tabindex="-1"><strong>四、闭幕与致谢</strong> <a class="header-anchor" href="#四、闭幕与致谢" aria-label="Permalink to &quot;**四、闭幕与致谢**&quot;">​</a></h4><ul><li>会议以 Nova Wolf 的 <strong>Musquin paddle song</strong> 结束，象征友好与合作。</li><li>主持人感谢社区成员参与，鼓励将会议内容传播至更多技术团队。</li></ul><p><strong>备注</strong>：</p><ul><li>原住民文化强调口述历史，本次会议未提供书面记录，但鼓励通过视频传播知识。</li><li>下次会议地点待定，可能扩展至欧洲或亚洲。</li><li>关键词保留：CRUSH, RADOS, OSD, Bluestore, erasure coding, Kubernetes, RESTful API, tiering.</li></ul>',12)])])}const c=n(s,[["render",l]]);export{h as __pageData,c as default};
